```yaml
name: Social Copy Generator

on:
  pull_request:
    types: [opened, synchronize]
  issue_comment:
    types: [created]

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  generate-social-copy:
    runs-on: ubuntu-latest
    if: |
      (github.event_name == 'pull_request' && github.event.action == 'opened') ||
      (github.event_name == 'issue_comment' && github.event.issue.pull_request && contains(github.event.comment.body, 'Generate social media copies'))
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 20

      - name: Install dependencies
        run: npm ci

      - name: Get PR Details
        id: pr_details
        uses: actions/github-script@v7
        with:
          script: |
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            core.setOutput('title', pr.data.title);
            core.setOutput('body', pr.data.body || '');
            core.setOutput('head_sha', pr.data.head.sha);
            core.setOutput('base_sha', pr.data.base.sha);

      - name: Get PR Diff
        id: diff
        run: |
          git diff ${{ steps.pr_details.outputs.base_sha }}..${{ steps.pr_details.outputs.head_sha }} > pr.diff
          echo "diff_size=$(wc -c < pr.diff)" >> $GITHUB_OUTPUT

      - name: Post Initial Comment
        if: github.event_name == 'pull_request' && github.event.action == 'opened'
        uses: actions/github-script@v7
        with:
          script: |
            const commentBody = `## Social Media Copy Generator 🚀

            Ready to generate social media content for this PR?

            - [ ] Generate social media copies

            *Check the box above to trigger Claude Code to analyze your changes and generate Twitter/X, LinkedIn, and Blog Post content.*`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: commentBody
            });

      - name: Update Comment to Generating
        if: github.event_name == 'issue_comment'
        uses: actions/github-script@v7
        with:
          script: |
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            let targetComment = comments.data.find(c => c.body.includes('Social Media Copy Generator'));

            if (targetComment) {
              const newBody = targetComment.body.replace(
                /- \[x\] Generate social media copies/,
                '- [ ] Generate social media copies\n\n*Generating... Please wait.*'
              );

              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: targetComment.data.id,
                body: newBody
              });
            }

      - name: Generate Social Copies with Claude
        if: github.event_name == 'issue_comment'
        id: generate
        run: |
          # Create a script to generate social copies
          cat > generate_social.js << 'EOF'
          const fs = require('fs');
          const { execSync } = require('child_process');

          const diff = fs.readFileSync('pr.diff', 'utf8');
          const title = process.env.PR_TITLE;
          const body = process.env.PR_BODY;

          // Simulate Claude Code generation (replace with actual Claude API call)
          const twitterCopy = `🚀 New feature in CopilotKit!\n\n${title}\n\n${body ? body.substring(0, 100) + '...' : ''}\n\n#CopilotKit #AI #OpenSource`;

          const linkedinCopy = `Excited to announce a new update to CopilotKit!\n\n${title}\n\n${body || 'Check out the changes in this PR.'}\n\n#CopilotKit #AI #DeveloperTools #OpenSource`;

          const blogPost = `# ${title}\n\n${body || 'A new update has been released.'}\n\n## What Changed\n\n${diff.substring(0, 500)}...\n\n## Why This Matters\n\nThis update improves the developer experience and adds new capabilities to CopilotKit.`;

          const output = JSON.stringify({
            twitter: twitterCopy,
            linkedin: linkedinCopy,
            blog: blogPost
          });

          fs.writeFileSync('social_copies.json', output);
          console.log(output);
          EOF

          PR_TITLE="${{ steps.pr_details.outputs.title }}" \
          PR_BODY="${{ steps.pr_details.outputs.body }}" \
          node generate_social.js

      - name: Update Comment with Results
        if: github.event_name == 'issue_comment' && success()
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const socialCopies = JSON.parse(fs.readFileSync('social_copies.json', 'utf8'));

            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            let targetComment = comments.data.find(c => c.body.includes('Social Media Copy Generator'));

            if (targetComment) {
              const newBody = `## Social Media Copy Generator 🚀

              ✅ Generated social media copies for this PR!

              ### Twitter/X
              \`\`\`
              ${socialCopies.twitter}
              \`\`\`

              ### LinkedIn
              \`\`\`
              ${socialCopies.linkedin}
              \`\`\`

              ### Blog Post
              \`\`\`
              ${socialCopies.blog}
              \`\`\`

              ---

              - [ ] Regenerate`;

              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: targetComment.data.id,
                body: newBody
              });
            }

      - name: Update Comment on Failure
        if: github.event_name == 'issue_comment' && failure()
        uses: actions/github-script@v7
        with:
          script: |
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            let targetComment = comments.data.find(c => c.body.includes('Social Media Copy Generator'));

            if (targetComment) {
              const newBody = `## Social Media Copy Generator 🚀

              ❌ Failed to generate social media copies.

              [View workflow logs](${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID})

              ---

              - [ ] Regenerate`;

              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: targetComment.data.id,
                body: newBody
              });
            }
